import{c as o,Q as t,j as a,m as s}from"./chunks/framework.g_l1frA7.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"help/changelog.md","filePath":"help/changelog.md","lastUpdated":null}'),n={name:"help/changelog.md"};function i(r,e,c,l,d,h){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>FinSight does not yet publish versioned GitHub Releases with changelog entries. Until it does, this page tracks notable delivery.</p><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><ul><li><strong>This docs site</strong> — VitePress under <code>docs/</code>, GitHub Pages workflow, <code>pnpm docs:*</code> scripts.</li><li>Self-hosting guide at <code>docs/self-hosting.md</code> remains authoritative for Docker/Tailscale/Caddy/LAN recipes.</li></ul><h2 id="how-to-track-changes" tabindex="-1">How to track changes <a class="header-anchor" href="#how-to-track-changes" aria-label="Permalink to &quot;How to track changes&quot;">​</a></h2><ul><li><strong>Git log</strong>: <code>git log --oneline --since=&quot;1 month ago&quot;</code></li><li><strong>Migrations</strong>: <code>crates/finsight-core/migrations/V016*</code> is the latest; next is <code>V017__</code>.</li><li><strong>OpenAPI</strong>: <code>openapi.json</code> diff after <code>pnpm openapi</code> shows typed contract changes.</li><li><strong>Server image</strong>: <code>ghcr.io/koushik0901/finsight:latest</code> — pin <code>FINSIGHT_IMAGE</code> in <code>.env</code> for reproducible deploys.</li></ul><p>When versioned Releases ship, this page will read from <code>CHANGELOG.md</code> and the Release notes. Until then, treat the commit history and the audit files in <code>docs/audits/</code> as the change record.</p><blockquote><p>This page intentionally makes no claims about release cadence or version numbers that do not yet exist.</p></blockquote>',8)])])}const u=o(n,[["render",i]]);export{p as __pageData,u as default};
